    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LA_0LA1RC_0RD0RB_1LC1RA | exact ok_iarm0_1_1RB1LA_0LA1RC_0RD0RB_1LC1RA]. }
    exfalso; lia.
