(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB1LA_0LA1RC_0RD0RB_1LC1RA : NeverQuasiHaltsTr tm_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
Proof.
  apply (boardph_neverqhtr tm_1RB1LA_0LA1RC_0RD0RB_1LC1RA pins_1RB1LA_0LA1RC_0RD0RB_1LC1RA FAM 1
                           iarm_1RB1LA_0LA1RC_0RD0RB_1LC1RA 1 1
                           farm_1RB1LA_0LA1RC_0RD0RB_1LC1RA 1 1
                           fm1_1RB1LA_0LA1RC_0RD0RB_1LC1RA fm2_1RB1LA_0LA1RC_0RD0RB_1LC1RA 0 vis_1RB1LA_0LA1RC_0RD0RB_1LC1RA
                           [1;0] 0 10).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact boot_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
  - lia.
  - exact iarm_sound_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
  - exact iarm_lhs_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
  - exact iarm_rhs_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
  - exact iarm_cb_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
  - lia.
  - lia.
  - exact farm_sound_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
  - exact farm_lhs_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
  - exact farm_rhs_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
  - exact farm_cb_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
  - exact vis_ok_1RB1LA_0LA1RC_0RD0RB_1LC1RA.
Qed.

