Lemma farm_sound_1RB1LA_1LC1RD_0RC1RA_0LA0RB : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_1RB1LA_1LC1RD_0RC1RA_0LA0RB r ph).
