    { eapply arm_sound; [exact rules_sound_1RB1LA_1LC1RD_0RC1RA_0LA0RB | exact ok_farm1_0_1RB1LA_1LC1RD_0RC1RA_0LA0RB]. }
    exfalso; lia.
