  match r, ph with
  | 1, 0 => farm1_0_1RB1LA_1RC1RC_0LA0RD_1RA1RC
  | _, _ => farm1_0_1RB1LA_1RC1RC_0LA0RD_1RA1RC  (* unreachable: 0 < r < N0 + st *)
