Definition iarm_1RB1LB_1LA1RC_1RA0LD_0RB1LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LB_1LA1RC_1RA0LD_0RB1LD
  | 1, 0 => iarm1_0_1RB1LB_1LA1RC_1RA0LD_0RB1LD
  | 2, 0 => iarm2_0_1RB1LB_1LA1RC_1RA0LD_0RB1LD
  | _, _ => iarm0_0_1RB1LB_1LA1RC_1RA0LD_0RB1LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

