    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LB_1LC0RD_1LA1RA_0LB1RD | exact ok_iarm0_1_1RB1LB_1LC0RD_1LA1RA_0LB1RD]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LB_1LC0RD_1LA1RA_0LB1RD | exact ok_iarm1_0_1RB1LB_1LC0RD_1LA1RA_0LB1RD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LB_1LC0RD_1LA1RA_0LB1RD | exact ok_iarm1_1_1RB1LB_1LC0RD_1LA1RA_0LB1RD]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LB_1LC0RD_1LA1RA_0LB1RD | exact ok_iarm2_0_1RB1LB_1LC0RD_1LA1RA_0LB1RD]. }
    destruct r as [|r].
